SELECT COUNT(1) FROM promotion_groups_activity g
INNER JOIN items i ON i.goods_id = g.goods_id AND i.company_id = g.company_id
WHERE g.company_id = #{companyId}
AND (g.disabled = 0 OR g.disabled IS NULL OR g.disabled = false)
AND i.item_id IN
#{id}
AND (
	(g.begin_time <= #{beginTime} AND g.end_time >= #{beginTime})
	OR (g.begin_time <= #{endTime} AND g.end_time >= #{endTime})
)

	AND g.groups_activity_id <> #{excludeGroupId}

SELECT COUNT(1) FROM promotions_bargain b
WHERE b.company_id = #{companyId}
AND CAST(b.item_id AS UNSIGNED) IN
#{id}
AND (
	(b.begin_time <= #{beginTime} AND b.end_time >= #{beginTime})
	OR (b.begin_time <= #{endTime} AND b.end_time >= #{endTime})
)

	AND b.bargain_id <> #{excludeBargainId}
